export function decodeGameReviewSnapshot(value: unknown): GameReviewSnapshot {
  const snapshot = decodeDefinition<GameReviewSnapshot>(
    "GameReviewSnapshot",
    value,
  )
  requireIncreasing(
    snapshot.evaluationTimeline.map(({ ply }) => ply),
    "$.evaluationTimeline",
  )
  requireIncreasing(
    snapshot.moments.map(({ ply }) => ply),
    "$.moments",
  )
  requireUnique(
    snapshot.moments.map(({ momentId }) => momentId),
    "$.moments",
  )
  if (
    snapshot.evaluationTimeline.some(({ ply }) => ply > snapshot.maxPly) ||
    snapshot.moments.some(({ ply }) => ply > snapshot.maxPly)
  ) {
    throw new ContractDecodeError(
      "$.maxPly",
      "must include every presented ply",
    )
  }
  for (const [index, moment] of snapshot.moments.entries()) {
    const path = `$.moments[${index}]`
    // Stepping to the next Critical Moment is an index step, so a gap or a
    // reorder here is the difference between "next" and "some other moment".
    if (moment.index !== index) {
      throw new ContractDecodeError(
        `${path}.index`,
        "must be contiguous and zero-based in ply order",
      )
    }
    requireNonEmpty(
      [
        moment.moveLabel,
        moment.glyph,
        moment.title,
        moment.summary,
        moment.board.announcement,
      ],
      path,
    )
    requireUnique(
      moment.board.pieces.map(({ pieceId }) => pieceId),
      `${path}.board.pieces`,
    )
    requireUnique(
      moment.board.pieces.map(({ square }) => square),
      `${path}.board.pieces`,
    )
    if (
      moment.selection.kind === "pipelineCriticalMoment"
        ? moment.selection.criticalMomentId !== moment.momentId
        : moment.selection.ply !== moment.ply
    ) {
      throw new ContractDecodeError(
        `${path}.selection`,
        "must name the exact snapshot Review Moment",
      )
    }
    for (const [arrowIndex, arrow] of moment.arrows.entries()) {
      requireNonEmpty([arrow.label], `${path}.arrows[${arrowIndex}]`)
      if (arrow.from === arrow.to) {
        throw new ContractDecodeError(
          `${path}.arrows[${arrowIndex}]`,
          "must describe a move between two squares",
        )
      }
    }
    requireUnique(moment.sequenceKinds, `${path}.sequenceKinds`)
  }
  return snapshot
}

