/**
 * A rendered continuation is one-based, contiguous, and every ply is a real
 * move on a real board, whichever address served it.
 */
function validateSequenceMoves(moves: MoveSequencePresentation["moves"]) {
  if (moves.length === 0) {
    throw new ContractDecodeError(
      "$.moves",
      "must contain at least one canonical move",
    )
  }
  moves.forEach((move, index) => {
    const path = `$.moves[${index}]`
    if (move.index !== index + 1) {
      throw new ContractDecodeError(
        `${path}.index`,
        "must be contiguous and one-based",
      )
    }
    requireNonEmpty([move.san, move.board.announcement], path)
    requireUnique(
      move.board.pieces.map(({ pieceId }) => pieceId),
      `${path}.board.pieces`,
    )
    requireUnique(
      move.board.pieces.map(({ square }) => square),
      `${path}.board.pieces`,
    )
    requireNonEmpty(
      move.board.pieces.map(({ pieceId }) => pieceId),
      `${path}.board.pieces`,
    )
    if (move.board.lastMove.from === move.board.lastMove.to) {
      throw new ContractDecodeError(
        `${path}.board.lastMove`,
        "must describe one move between distinct squares",
      )
    }
  })
}

/**
 * A Review Moment offers at most one continuation of each kind, and a
 * continuation's move count is what a surface renders before reading the moves.
 */
function validateSnapshotSequences(
  sequences: ReviewMomentSnapshot["sequences"],
  path: string,
) {
  requireUnique(
    sequences.map(({ kind }) => kind),
    `${path}.sequences`,
  )
  for (const [index, sequence] of sequences.entries()) {
    const sequencePath = `${path}.sequences[${index}]`
    requireNonEmpty([sequence.title], sequencePath)
    if (sequence.san.length !== sequence.moveCount) {
      throw new ContractDecodeError(
        `${sequencePath}.moveCount`,
        "must count the referenced moves",
      )
    }
  }
}

